<template><div class="page"><header><div><h2>成绩评定</h2><p>按课程配置成绩项、保存草稿并统一发布</p></div><select v-model="courseId" @change="loadGrade"><option :value="0">请选择课程</option><option v-for="c in courses" :key="c.courseId" :value="c.courseId">{{ c.courseName }}</option></select></header><p v-if="message" class="error">{{ message }}</p><template v-if="courseId"><section class="toolbar"><div><strong>成绩项</strong><span v-for="i in items" :key="i.gradeItemId">{{ i.itemName }} {{ i.itemWeight }}%</span><em>合计 {{ weightTotal }}%</em></div><button :disabled="published" @click="itemDialog=true">新增成绩项</button><button :disabled="published||items.length===0" @click="saveAll">保存草稿</button><button class="primary" :disabled="published||weightTotal!==100" @click="publish">发布成绩</button></section><section class="card"><div v-if="items.length===0" class="empty">请先添加成绩项</div><div v-else-if="sheets.length===0" class="empty">课程暂无选课学生</div><div v-else class="scroll"><table><thead><tr><th>学生</th><th v-for="i in items" :key="i.gradeItemId">{{ i.itemName }} / {{ i.fullScore }}</th><th>总评</th></tr></thead><tbody><tr v-for="s in sheets" :key="s.studentId"><td>{{ s.studentName }}<small>{{ s.studentNo }}</small></td><td v-for="i in items" :key="i.gradeItemId"><input v-model.number="scores[key(s.studentId,i.gradeItemId)]" type="number" min="0" :max="i.fullScore" :disabled="published"/></td><td>{{ s.totalScore??'—' }}</td></tr></tbody></table></div></section></template><div v-else class="empty">选择课程后开始成绩评定</div><teleport to="body"><div v-if="itemDialog" class="overlay" @click.self="itemDialog=false"><section class="modal"><h3>新增成绩项</h3><label>名称<input v-model.trim="itemForm.itemName"/></label><label>类型<select v-model="itemForm.itemType"><option :value="1">任务</option><option :value="2">平时</option><option :value="3">期末</option><option :value="4">其他</option></select></label><label>权重（%）<input v-model.number="itemForm.itemWeight" type="number" min="1" max="100"/></label><label>满分<input v-model.number="itemForm.fullScore" type="number" min="1"/></label><footer><button @click="itemDialog=false">取消</button><button class="primary" @click="addItem">保存</button></footer></section></div></teleport></div></template>
<script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import{createGradeItem,getCourseGradeSheets,getCoursePage,getGradeItems,publishCourseGrades,saveGradeDrafts,type CourseListItem,type GradeItem,type StudentGradeSheet}from'../../utils/teachingApi';const courses=ref<CourseListItem[]>([]),courseId=ref(0),items=ref<GradeItem[]>([]),sheets=ref<StudentGradeSheet[]>([]),itemDialog=ref(false),message=ref('');const scores=reactive<Record<string,number|undefined>>({});const itemForm=reactive({itemName:'',itemType:1,itemWeight:0,fullScore:100});const key=(s:number,i:number)=>`${s}-${i}`;const weightTotal=computed(()=>items.value.reduce((n,i)=>n+Number(i.itemWeight),0));const published=computed(()=>sheets.value.some(s=>s.publishStatus!==1));const err=(e:unknown)=>e instanceof Error?e.message:'操作失败';async function loadGrade(){if(!courseId.value)return;try{[items.value,sheets.value]=await Promise.all([getGradeItems(courseId.value),getCourseGradeSheets(courseId.value)]);for(const s of sheets.value)for(const i of s.items)scores[key(s.studentId,i.gradeItemId)]=i.score??undefined}catch(e){message.value=err(e)}}async function addItem(){if(!itemForm.itemName||itemForm.itemWeight<=0||itemForm.fullScore<=0)return;try{await createGradeItem(courseId.value,{itemName:itemForm.itemName,itemType:itemForm.itemType,itemWeight:itemForm.itemWeight,fullScore:itemForm.fullScore,sortNo:items.value.length});itemDialog.value=false;Object.assign(itemForm,{itemName:'',itemType:1,itemWeight:0,fullScore:100});await loadGrade()}catch(e){message.value=err(e)}}async function saveAll(){const data=[] as {gradeItemId:number;studentId:number;score:number}[];for(const s of sheets.value)for(const i of items.value){const v=scores[key(s.studentId,i.gradeItemId)];if(v!==undefined)data.push({gradeItemId:i.gradeItemId,studentId:s.studentId,score:v})}if(!data.length){message.value='请至少录入一项成绩';return}try{await saveGradeDrafts(courseId.value,data);message.value='成绩草稿已保存';await loadGrade()}catch(e){message.value=err(e)}}async function publish(){if(!confirm('发布后成绩将锁定，确认发布？'))return;try{await publishCourseGrades(courseId.value);message.value='成绩已发布';await loadGrade()}catch(e){message.value=err(e)}}onMounted(async()=>{try{courses.value=(await getCoursePage({pageNum:1,pageSize:500})).records}catch(e){message.value=err(e)}});
</script><style scoped>.page{height:100%;overflow:auto;padding:28px 36px;background:transparent;color:#172033}header{display:flex;justify-content:space-between;align-items:center}h2{margin:0}header p{color:#7b8495}header select,.toolbar button,.modal button{border:1px solid #dfe4ec;border-radius:8px;padding:9px;background:#fff}.toolbar{display:flex;align-items:center;gap:10px;margin:18px 0;padding:14px;background:#fff;border:1px solid #e7ebf1;border-radius:12px}.toolbar div{flex:1;display:flex;gap:10px;align-items:center}.toolbar span{padding:4px 8px;background:#eff6ff;color:#1d4ed8;font-size:12px}.toolbar em{font-size:12px;color:#7b8495}.primary{background:#2563eb!important;color:#fff!important;border:0!important}.card{background:#fff;border:1px solid #e7ebf1;border-radius:12px;overflow:hidden}.scroll{overflow:auto}table{width:100%;min-width:700px;border-collapse:collapse}th,td{padding:12px;border-bottom:1px solid #eef1f5;text-align:left;font-size:13px}th{background:#fafbfc;color:#687386}td small{display:block;color:#9098a7}td input{width:80px;border:1px solid #dfe4ec;border-radius:7px;padding:7px}.empty{text-align:center;padding:60px;color:#8992a2}.error{color:#b42336}.overlay{position:fixed;inset:0;z-index:1200;display:flex;align-items:center;justify-content:center;background:#0f172a6b}.modal{width:420px;padding:22px;background:#fff;border-radius:14px}.modal label{display:flex;flex-direction:column;gap:5px;margin:12px 0;font-size:12px}.modal input,.modal select{border:1px solid #dfe4ec;border-radius:8px;padding:9px}.modal footer{display:flex;justify-content:flex-end;gap:8px}@media(max-width:800px){.toolbar,.toolbar div{align-items:flex-start;flex-direction:column}}</style>
